self.addEventListener('activate',e=>{e.waitUntil((async()=>{const dst=await caches.open(CACHE);for(const name of await caches.keys()){if(!name.startsWith(PREFIX)||name===CACHE)continue;const old=await caches.open(name);for(const req of await old.keys()){const u=new URL(req.url),p=u.pathname.slice(scope.pathname.length);if(u.origin!==scope.origin||u.searchParams.get('asset')===VERSIONS[p]){const res=await old.match(req);if(res)await dst.put(req,res)}}await caches.delete(name)}await self.clients.claim()})())});
